package com.smarthub.plus
import android.content.Context
import android.graphics.*
import okhttp3.*
import java.util.concurrent.TimeUnit
class ChannelLogoResolver(private val context:Context,private val db:ChannelAliasDatabase){
 fun resolve(name:String):Bitmap?{val e=db.channel(name);if(e!=null)try{image(e)?.let{return it}}catch(_:Exception){};val matched=ChannelCatalogue(context).logo(name,e?.id?:"");for(url in DuplicateLogoChoices.choose(matched,LogoSelection.seed(context),name).take(3))try{return download(url)}catch(_:Exception){};return null}
 fun image(e:ChannelAliasDatabase.Entry):Bitmap?{if(e.asset.isNotEmpty())try{return decode(context.assets.open("logo-resolver/"+e.asset).use{it.readBytes()})}catch(_:Exception){};return if(e.url.isEmpty())null else download(e.url)}
 fun download(url:String):Bitmap{networkRequests.incrementAndGet();require(java.net.URI(url).let{it.scheme=="https"&&it.host!=null&&it.userInfo==null});HTTP.newCall(Request.Builder().url(url).header("User-Agent","IRAQhub/2.4 logo resolver").build()).execute().use{r->check(r.isSuccessful);val input=r.body!!.byteStream();val out=java.io.ByteArrayOutputStream();input.use{val buf=ByteArray(8192);while(true){val n=it.read(buf);if(n<0)break;require(out.size()+n<=4*1024*1024);out.write(buf,0,n)}};return decode(out.toByteArray())}}
 private fun decode(bytes:ByteArray):Bitmap{val prefix=String(bytes.take(200).toByteArray());if(prefix.contains("<svg")||prefix.contains("<?xml")){val xml=String(bytes);require(!xml.contains("<!DOCTYPE",true)&&!xml.contains("<!ENTITY",true));val svg=com.caverock.androidsvg.SVG.getFromString(xml);val ratio=svg.documentAspectRatio.takeIf{it.isFinite()&&it>0}?:1f;val w=if(ratio>=1)512 else (512*ratio).toInt().coerceAtLeast(1);val h=if(ratio>=1)(512/ratio).toInt().coerceAtLeast(1) else 512;svg.setDocumentWidth(w.toFloat());svg.setDocumentHeight(h.toFloat());return Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888).also{Canvas(it).drawPicture(svg.renderToPicture(w,h))}};val o=BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.size,o);require(o.outWidth in 1..10000&&o.outHeight in 1..10000);o.inSampleSize=1;while(o.outWidth/o.inSampleSize>512||o.outHeight/o.inSampleSize>512)o.inSampleSize*=2;o.inJustDecodeBounds=false;return requireNotNull(BitmapFactory.decodeByteArray(bytes,0,bytes.size,o))}
 companion object{@JvmField val networkRequests=java.util.concurrent.atomic.AtomicInteger();private val HTTP=OkHttpClient.Builder().connectTimeout(3,TimeUnit.SECONDS).readTimeout(5,TimeUnit.SECONDS).callTimeout(8,TimeUnit.SECONDS).followSslRedirects(false).build()}
}
